    ('0025b0ba-fd74-4c08-96e3-acc17956aa44'::uuid, 'site_type', 'City/town/settlement', 'Archaeological site', 'journal-reversal-3-rollback:0025b0ba-fd74-4c08-96e3-acc17956aa44:site_type', 'rollback of journal-reversal-3: site_type ''Archaeological site'' restored on Horvat Shema', '[{"source": "remediation_change_log:28566", "url": "remediation_change_log", "quote": "phase3:batch-0161:chunk-0001 (P3/site_type): site_type ''City/town/settlement'' -> ''Archaeological site'' - the write this row undoes"}, {"source": "opus:phase3:6bb704e6b321e34ae3428bbcd5363e47b494eb09a16982d860604d6c4c479e1b", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "archaeological site located in Israel at the foot of Mount Meron"}, {"source": "opus:phase3:6bb704e6b321e34ae3428bbcd5363e47b494eb09a16982d860604d6c4c479e1b", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "It features the ruins of a large Jewish village of the Roman and Byzantine periods, including the remains of an ancient synagogue and a mausoleum."}, {"source": "opus:phase3:6bb704e6b321e34ae3428bbcd5363e47b494eb09a16982d860604d6c4c479e1b", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "It features the ruins of a large Jewish village"}, {"source": "opus:phase3:6bb704e6b321e34ae3428bbcd5363e47b494eb09a16982d860604d6c4c479e1b", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "of the Roman and Byzantine periods, including the remains of an ancient synagogue and a mausoleum."}, {"source": "residual", "url": "REASONS.json", "quote": "The field is open again, not corrected: the reversal withdraws a write the Opus re-verification did not confirm, and does not claim the restored value is right (opus_audit/RULES.md)."}]'::jsonb),
    ('008ecaa5-ce9b-484d-9eb8-0f27659bc91d'::uuid, 'period_name', '< 4500 BC', '4500 - 3000 BC', 'journal-reversal-3-rollback:008ecaa5-ce9b-484d-9eb8-0f27659bc91d:period_name', 'rollback of journal-reversal-3: period_name ''4500 - 3000 BC'' restored on Fort Abbas', '[{"source": "remediation_change_log:30330", "url": "remediation_change_log", "quote": "2026-09-22_mechanical-period-name (P6/period-name-bucket): period_name ''< 4500 BC'' -> ''4500 - 3000 BC'' - the write this row undoes"}, {"source": "journal", "url": "remediation_change_log.evidence", "quote": "phase3:batch-0128:chunk-0001 (P3/period_start): period_start ''-5000'' -> ''-4000'' - the write that left the label behind"}, {"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-5000) = ''< 4500 BC'' - the period_start the site is left with"}]'::jsonb),
    ('008ecaa5-ce9b-484d-9eb8-0f27659bc91d'::uuid, 'period_start', '-5000', '-4000', 'journal-reversal-3-rollback:008ecaa5-ce9b-484d-9eb8-0f27659bc91d:period_start', 'rollback of journal-reversal-3: period_start ''-4000'' restored on Fort Abbas', '[{"source": "remediation_change_log:28410", "url": "remediation_change_log", "quote": "phase3:batch-0128:chunk-0001 (P3/period_start): period_start ''-5000'' -> ''-4000'' - the write this row undoes"}, {"source": "opus:phase3:d722bbffe38da88e6d4455a7f88f0d5c38e1eed658fbfd2c10a02a5e6b756fac", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "Archaeological investigations in the Cholistan Desert have recorded hundreds of ancient settlement sites along the dry riverbed."}, {"source": "opus:phase3:d722bbffe38da88e6d4455a7f88f0d5c38e1eed658fbfd2c10a02a5e6b756fac", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "In 1927, during the rule of Nawab Sadiq Muhammad Khan V of the Bahawalpur State, the settlement was renamed Fort Abbas in honor of his son Muhammad Abbas."}, {"source": "opus:phase3:d722bbffe38da88e6d4455a7f88f0d5c38e1eed658fbfd2c10a02a5e6b756fac", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "Surveys conducted by early researchers and later archaeologists documented continuous human occupation dating back to the fourth millennium BCE."}, {"source": "opus:phase3:d722bbffe38da88e6d4455a7f88f0d5c38e1eed658fbfd2c10a02a5e6b756fac", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "A survey of the Cholistan region from 1947 to 1977 dated Hakra ceramics to 5000 BCE."}, {"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-5000) = ''< 4500 BC'', categorize_period(-4000) = ''4500 - 3000 BC'' - another bucket"}, {"source": "residual", "url": "REASONS.json", "quote": "The field is open again, not corrected: the reversal withdraws a write the Opus re-verification did not confirm, and does not claim the restored value is right (opus_audit/RULES.md)."}]'::jsonb),
    ('00a511c2-7790-4b06-aa1b-0b3e1e55cbf4'::uuid, 'site_type', 'City/town/settlement', 'Archaeological site', 'journal-reversal-3-rollback:00a511c2-7790-4b06-aa1b-0b3e1e55cbf4:site_type', 'rollback of journal-reversal-3: site_type ''Archaeological site'' restored on Archaeological Site of Alba-la-Romaine', '[{"source": "remediation_change_log:29548", "url": "remediation_change_log", "quote": "phase3:batch-0306:chunk-0001 (P3/site_type): site_type ''City/town/settlement'' -> ''Archaeological site'' - the write this row undoes"}, {"source": "opus:phase3:10aed9ba151fb1842e43f0abf6bb24dce880da919ffd22cbfe5b5d74d51b918e", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "There are also the remains of a Roman city and a medieval village in the commune."}, {"source": "opus:phase3:10aed9ba151fb1842e43f0abf6bb24dce880da919ffd22cbfe5b5d74d51b918e", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "archaeological site in Alba-la-Romaine, France"}, {"source": "opus:phase3:10aed9ba151fb1842e43f0abf6bb24dce880da919ffd22cbfe5b5d74d51b918e", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "correspondant à la ville gallo-romaine d''Alba Helviorum"}, {"source": "residual", "url": "REASONS.json", "quote": "The field is open again, not corrected: the reversal withdraws a write the Opus re-verification did not confirm, and does not claim the restored value is right (opus_audit/RULES.md)."}]'::jsonb),
    ('00c2b26f-d007-4c02-a5da-403f14f8daa5'::uuid, 'site_type', 'City/town/settlement', 'Archaeological site', 'journal-reversal-3-rollback:00c2b26f-d007-4c02-a5da-403f14f8daa5:site_type', 'rollback of journal-reversal-3: site_type ''Archaeological site'' restored on Wamanmarka, Lima', '[{"source": "remediation_change_log:28956", "url": "remediation_change_log", "quote": "phase3:batch-0218:chunk-0001 (P3/site_type): site_type ''City/town/settlement'' -> ''Archaeological site'' - the write this row undoes"}, {"source": "opus:phase3:639fb70abb3ddc7851deb10592f0e64552d46e2bcf5e3974213ba99b600d40bc", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "Wamanmarka or Waman Marka (Quechua waman falcon, marka village, Hispanicized spelling Huamanmarca) is a pre-Hispanic archaeological site in the Lima Region of Peru."}, {"source": "opus:phase3:639fb70abb3ddc7851deb10592f0e64552d46e2bcf5e3974213ba99b600d40bc", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "los antiguos pobladores de la cultura Yauyos se establezcan en este impresionante lugar en un número aproximado de 2,000"}, {"source": "opus:phase3:639fb70abb3ddc7851deb10592f0e64552d46e2bcf5e3974213ba99b600d40bc", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "Estas construcciones datan aproximadamente de 1,200 d.C., son del intermedio tardío"}, {"source": "opus:phase3:639fb70abb3ddc7851deb10592f0e64552d46e2bcf5e3974213ba99b600d40bc", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "archaeological site in the Lima Region, Peru"}, {"source": "residual", "url": "REASONS.json", "quote": "The field is open again, not corrected: the reversal withdraws a write the Opus re-verification did not confirm, and does not claim the restored value is right (opus_audit/RULES.md)."}]'::jsonb),
