    ('0415d29e-5239-40c6-ab1d-5b19e443336b'::uuid, 'period_start', '-4000', '-3000', 'journal-reversal-3-rollback:0415d29e-5239-40c6-ab1d-5b19e443336b:period_start', 'rollback of journal-reversal-3: period_start ''-3000'' restored on Odigitria', '[{"source": "remediation_change_log:29652", "url": "remediation_change_log", "quote": "phase3:batch-0320:chunk-0001 (P3/period_start): period_start ''-4000'' -> ''-3000'' - the write this row undoes"}, {"source": "opus:phase3:5dc129779b7ac4dec43b9c8435fe1db64e0231c1d8a385a531b37392a0c88176", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "The tombs are dated from Early Minoan I to Middle Minoan IA"}, {"source": "opus:phase3:5dc129779b7ac4dec43b9c8435fe1db64e0231c1d8a385a531b37392a0c88176", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "EM I (c. 3100–2650 BC) is marked by the appearance of the first painted ceramics."}, {"source": "opus:phase3:5dc129779b7ac4dec43b9c8435fe1db64e0231c1d8a385a531b37392a0c88176", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "The tombs are dated from Early Minoan I to Middle Minoan IA and were excavated in 1979 by N. Dimopoulou and in 1980 by Antonis Vasilakis."}, {"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-4000) = ''4500 - 3000 BC'', categorize_period(-3000) = ''3000 - 1500 BC'' - another bucket"}, {"source": "residual", "url": "REASONS.json", "quote": "The field is open again, not corrected: the reversal withdraws a write the Opus re-verification did not confirm, and does not claim the restored value is right (opus_audit/RULES.md)."}]'::jsonb),
    ('041bcb70-5676-4ef5-bab2-07f2153098c0'::uuid, 'site_type', 'City/town/settlement', 'Archaeological site', 'journal-reversal-3-rollback:041bcb70-5676-4ef5-bab2-07f2153098c0:site_type', 'rollback of journal-reversal-3: site_type ''Archaeological site'' restored on Menelaion', '[{"source": "remediation_change_log:28238", "url": "remediation_change_log", "quote": "phase3:batch-0099:chunk-0001 (P3/site_type): site_type ''City/town/settlement'' -> ''Archaeological site'' - the write this row undoes"}, {"source": "opus:phase3:2dabe7b28b277e63344da4330642bd20d03f59377c1830284c2cedc98065b12b", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "major settlement of the Mycenaean period in the Menelaion"}, {"source": "opus:phase3:2dabe7b28b277e63344da4330642bd20d03f59377c1830284c2cedc98065b12b", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "Around the 8th century BC, the Spartans built a monumental hero-shrine directly over the ruins, naming it Menelaion."}, {"source": "opus:phase3:2dabe7b28b277e63344da4330642bd20d03f59377c1830284c2cedc98065b12b", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "revealed few Middle Helladic findings on the Northern hill and major settlement of the Mycenaean period in the Menelaion."}, {"source": "residual", "url": "REASONS.json", "quote": "The field is open again, not corrected: the reversal withdraws a write the Opus re-verification did not confirm, and does not claim the restored value is right (opus_audit/RULES.md)."}]'::jsonb),
    ('042c8c7f-1ec1-485a-ba0b-3ab847320ee7'::uuid, 'period_name', '500 - 1000 AD', '1 - 500 AD', 'journal-reversal-3-rollback:042c8c7f-1ec1-485a-ba0b-3ab847320ee7:period_name', 'rollback of journal-reversal-3: period_name ''1 - 500 AD'' restored on Labna', '[{"source": "remediation_change_log:30334", "url": "remediation_change_log", "quote": "2026-09-22_mechanical-period-name (P6/period-name-bucket): period_name ''500 - 1000 AD'' -> ''1 - 500 AD'' - the write this row undoes"}, {"source": "journal", "url": "remediation_change_log.evidence", "quote": "phase3:batch-0197:chunk-0001 (P3/period_start): period_start ''500'' -> ''200'' - the write that left the label behind"}, {"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(500) = ''500 - 1000 AD'' - the period_start the site is left with"}]'::jsonb),
    ('042c8c7f-1ec1-485a-ba0b-3ab847320ee7'::uuid, 'period_start', '500', '200', 'journal-reversal-3-rollback:042c8c7f-1ec1-485a-ba0b-3ab847320ee7:period_start', 'rollback of journal-reversal-3: period_start ''200'' restored on Labna', '[{"source": "remediation_change_log:28812", "url": "remediation_change_log", "quote": "phase3:batch-0197:chunk-0001 (P3/period_start): period_start ''500'' -> ''200'' - the write this row undoes"}, {"source": "opus:phase3:b35482d038b3a26e27b415fcd25d6e37e7a689162a03a4acc26b0a6838216fbc", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "El sitio estuvo poblado desde el año 200 a.C. y alcanzó su apogeo entre el año 800 y el 1000."}, {"source": "opus:phase3:b35482d038b3a26e27b415fcd25d6e37e7a689162a03a4acc26b0a6838216fbc", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "Cronología: 200 a. C. a 1000 d. C."}, {"source": "opus:phase3:b35482d038b3a26e27b415fcd25d6e37e7a689162a03a4acc26b0a6838216fbc", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "The city existed from 200 to 1000 AD."}, {"source": "opus:phase3:b35482d038b3a26e27b415fcd25d6e37e7a689162a03a4acc26b0a6838216fbc", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "Cronología: 200 a. C. a 1000 d. C. Ubicación cronológica principal: Clásico Tardío y Posclásico Temprano, 800 a 1000 d.C."}, {"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(500) = ''500 - 1000 AD'', categorize_period(200) = ''1 - 500 AD'' - another bucket"}, {"source": "residual", "url": "REASONS.json", "quote": "The field is open again, not corrected: the reversal withdraws a write the Opus re-verification did not confirm, and does not claim the restored value is right (opus_audit/RULES.md). A judge proposed ''-200''; it is not written here (RULES.md rule 5)."}]'::jsonb),
    ('042c8c7f-1ec1-485a-ba0b-3ab847320ee7'::uuid, 'site_type', 'City/town/settlement', 'Archaeological site', 'journal-reversal-3-rollback:042c8c7f-1ec1-485a-ba0b-3ab847320ee7:site_type', 'rollback of journal-reversal-3: site_type ''Archaeological site'' restored on Labna', '[{"source": "remediation_change_log:28813", "url": "remediation_change_log", "quote": "phase3:batch-0197:chunk-0001 (P3/site_type): site_type ''City/town/settlement'' -> ''Archaeological site'' - the write this row undoes"}, {"source": "opus:phase3:09cace26df6709a081e9bdff5c35ad51ddf3bca28ce79a5d9f65a927584e1ae6", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "It is estimated that about 3,000 inhabitants lived in Labna."}, {"source": "opus:phase3:09cace26df6709a081e9bdff5c35ad51ddf3bca28ce79a5d9f65a927584e1ae6", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "Si bien es una ciudad pequeña, resguarda tres joyas"}, {"source": "opus:phase3:09cace26df6709a081e9bdff5c35ad51ddf3bca28ce79a5d9f65a927584e1ae6", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "It undoubtedly had a complex social organization and shares style and decorative elements with other cities in the region"}, {"source": "opus:phase3:09cace26df6709a081e9bdff5c35ad51ddf3bca28ce79a5d9f65a927584e1ae6", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "Se estima que la ciudad tuvo una extensión de 2,2 km² y se ha calculado que pudo alojar una población de 3000 habitantes o quizá un poco más."}, {"source": "residual", "url": "REASONS.json", "quote": "The field is open again, not corrected: the reversal withdraws a write the Opus re-verification did not confirm, and does not claim the restored value is right (opus_audit/RULES.md)."}]'::jsonb),
    ('0490ef6d-5381-449d-aa8c-385ab7dbd8e7'::uuid, 'period_start', '-4500', '-4100', 'journal-reversal-3-rollback:0490ef6d-5381-449d-aa8c-385ab7dbd8e7:period_start', 'rollback of journal-reversal-3: period_start ''-4100'' restored on Xagħra Stone Circle', '[{"source": "remediation_change_log:28476", "url": "remediation_change_log", "quote": "phase3:batch-0141:chunk-0001 (P3/period_start): period_start ''-4500'' -> ''-4100'' - the write this row undoes"}, {"source": "opus:phase3:72852f0600f29710e9bf5099081ebf7c0b26267f9891cbc9868405505a43578e", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "It mainly dates back to around 3000 to 2400 BC, although the earliest tombs at the site date back to 4100 to 3800 BC."}, {"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-4500) = ''4500 - 3000 BC'', categorize_period(-4100) = ''4500 - 3000 BC'' - the same bucket"}, {"source": "residual", "url": "REASONS.json", "quote": "The field is open again, not corrected: the reversal withdraws a write the Opus re-verification did not confirm, and does not claim the restored value is right (opus_audit/RULES.md)."}]'::jsonb),
