    ('1e6efd70-020c-43b7-a63c-495eefa5a972'::uuid, 'period_start', '-6000', '-5300', 'journal-reversal-3-rollback:1e6efd70-020c-43b7-a63c-495eefa5a972:period_start', 'rollback of journal-reversal-3: period_start ''-5300'' restored on La Draga', '[{"source": "remediation_change_log:28570", "url": "remediation_change_log", "quote": "phase3:batch-0162:chunk-0001 (P3/period_start): period_start ''-6000'' -> ''-5300'' - the write this row undoes"}, {"source": "opus:phase3:853bf5205c8d563c11a710427c4062a45999bfb4c3112cb9c3d999ea3a287992", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "During the older phase (5.290-5.200 cal BC) the settlement can be described as a pile dwelling site"}, {"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-6000) = ''< 4500 BC'', categorize_period(-5300) = ''< 4500 BC'' - the same bucket"}, {"source": "residual", "url": "REASONS.json", "quote": "The field is open again, not corrected: the reversal withdraws a write the Opus re-verification did not confirm, and does not claim the restored value is right (opus_audit/RULES.md)."}]'::jsonb),
    ('1fd1292d-5dbf-4bbf-a501-6a0e094da785'::uuid, 'period_start', '-1500', '-700', 'journal-reversal-3-rollback:1fd1292d-5dbf-4bbf-a501-6a0e094da785:period_start', 'rollback of journal-reversal-3: period_start ''-700'' restored on Argura', '[{"source": "remediation_change_log:28977", "url": "remediation_change_log", "quote": "phase3:batch-0220:chunk-0001 (P3/period_start): period_start ''-1500'' -> ''-700'' - the write this row undoes"}, {"source": "opus:phase3:4d205f5daae12456440c30ee3ed6f5b113be60e84d8b41f8e8f73c94deae65e0", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "The ceramic material found covers from the seventh century BCE to the third century CE."}, {"source": "opus:phase3:4d205f5daae12456440c30ee3ed6f5b113be60e84d8b41f8e8f73c94deae65e0", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "Excavations on the mound in 1955-58 turned up sherds from the Geometric through Roman periods as well as prehistoric."}, {"source": "opus:phase3:4d205f5daae12456440c30ee3ed6f5b113be60e84d8b41f8e8f73c94deae65e0", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "identify the site of Agura with a place called Gremnos Magoula, approximately 7 kilometres (4.3 mi) west of Larissa"}, {"source": "opus:phase3:4d205f5daae12456440c30ee3ed6f5b113be60e84d8b41f8e8f73c94deae65e0", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "The site was first settled in the Aceramic Neolithic and continued to be occupied throughout the Neolithic and Bronze Ages."}, {"source": "opus:phase3:4d205f5daae12456440c30ee3ed6f5b113be60e84d8b41f8e8f73c94deae65e0", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "The mound served as the acropolis of Mycenaean Argissa and Classical Argyra."}, {"source": "opus:phase3:4d205f5daae12456440c30ee3ed6f5b113be60e84d8b41f8e8f73c94deae65e0", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "Available data also indicates that domestication of cattle occurred at Argissa as early as c. 6300 BC, during the Pre-Pottery Neolithic."}, {"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-1500) = ''1500 - 500 BC'', categorize_period(-700) = ''1500 - 500 BC'' - the same bucket"}, {"source": "residual", "url": "REASONS.json", "quote": "The field is open again, not corrected: the reversal withdraws a write the Opus re-verification did not confirm, and does not claim the restored value is right (opus_audit/RULES.md). A judge proposed ''-6300''; it is not written here (RULES.md rule 5)."}]'::jsonb),
