    ('3ccc24a7-a41a-4c7b-91e2-246b6b81ef05'::uuid, 'period_start', '-500', '-44', 'journal-reversal-3-rollback:3ccc24a7-a41a-4c7b-91e2-246b6b81ef05:period_start', 'rollback of journal-reversal-3: period_start ''-44'' restored on Augusta Raurica', '[{"source": "remediation_change_log:27946", "url": "remediation_change_log", "quote": "phase3:batch-0034:chunk-0001 (P3/period_start): period_start ''-500'' -> ''-44'' - the write this row undoes"}, {"source": "opus:phase3:e9dcd9cfd4c2f249b3ab3a6d388b6e487103aed50c91b28f8c0f7961ba0d1739", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "No archaeological evidence from this period has yet been found, leading to the conclusion that, either the settlement of the colony was disturbed by the civil war following the death of Julius Caesar, or that Plancus'' colony was actually in the area of modern Basel, not Augst."}, {"source": "opus:phase3:e9dcd9cfd4c2f249b3ab3a6d388b6e487103aed50c91b28f8c0f7961ba0d1739", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "Successful colonization of the site had to wait for Augustus'' conquest of the central Alps around 15 BC. The oldest find to date at Augusta Raurica has been dated to 6 BC by dendrochronology."}, {"source": "opus:phase3:e9dcd9cfd4c2f249b3ab3a6d388b6e487103aed50c91b28f8c0f7961ba0d1739", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "The oldest find to date at Augusta Raurica has been dated to 6 BC by dendrochronology."}, {"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-500) = ''500 BC - 1 AD'', categorize_period(-44) = ''500 BC - 1 AD'' - the same bucket"}, {"source": "residual", "url": "REASONS.json", "quote": "The field is open again, not corrected: the reversal withdraws a write the Opus re-verification did not confirm, and does not claim the restored value is right (opus_audit/RULES.md)."}]'::jsonb),
