    ('4154f90b-74f1-49d4-bdab-caa7bb1322fb'::uuid, 'site_type', 'City/town/settlement', 'Archaeological site', 'journal-reversal-3-rollback:4154f90b-74f1-49d4-bdab-caa7bb1322fb:site_type', 'rollback of journal-reversal-3: site_type ''Archaeological site'' restored on Jublains Archaeological Site', '[{"source": "remediation_change_log:28406", "url": "remediation_change_log", "quote": "phase3:batch-0127:chunk-0001 (P3/site_type): site_type ''City/town/settlement'' -> ''Archaeological site'' - the write this row undoes"}, {"source": "opus:phase3:94f7bb85f6379d5d67dc7a6d561dde2da70b1e4d5fd2a6af49b2862b9ea4e375", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "est fondée, chef-lieu des Diablintes dans la réorganisation du territoire opérée par Auguste."}, {"source": "opus:phase3:94f7bb85f6379d5d67dc7a6d561dde2da70b1e4d5fd2a6af49b2862b9ea4e375", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "archaeological site in Jublains, France"}, {"source": "opus:phase3:94f7bb85f6379d5d67dc7a6d561dde2da70b1e4d5fd2a6af49b2862b9ea4e375", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "Roman imperial authorities built a city named Noviodunum on the site of a temple of the Celtic Diablintes, which became the capital of this people in the Augustan administrative reorganization."}, {"source": "opus:phase3:94f7bb85f6379d5d67dc7a6d561dde2da70b1e4d5fd2a6af49b2862b9ea4e375", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "Urbanisation of the site began around the year 20, but in a disorganized manner."}, {"source": "residual", "url": "REASONS.json", "quote": "The field is open again, not corrected: the reversal withdraws a write the Opus re-verification did not confirm, and does not claim the restored value is right (opus_audit/RULES.md)."}]'::jsonb),
