    ('50d4292b-caee-4819-8aaa-64b94187fce8'::uuid, 'period_start', '-1500', '-1390', 'journal-reversal-3-rollback:50d4292b-caee-4819-8aaa-64b94187fce8:period_start', 'rollback of journal-reversal-3: period_start ''-1390'' restored on Serapeum of Saqqara', '[{"source": "remediation_change_log:29674", "url": "remediation_change_log", "quote": "phase3:batch-0324:chunk-0001 (P3/period_start): period_start ''-1500'' -> ''-1390'' - the write this row undoes"}, {"source": "opus:phase3:8b24dc9e78606550571cbfad88325d266d65c09e93f170e3da164eb1207b655c", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "The most ancient burials at the Serapeum, found in isolated tombs, date back to the reign of Amenhotep III of the Eighteenth Dynasty in the 14th century BC."}, {"source": "opus:phase3:8b24dc9e78606550571cbfad88325d266d65c09e93f170e3da164eb1207b655c", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "from the New Kingdom of Egypt to the end of the Ptolemaic Period, at least sixty Apis are attested to have been interred at the Serapeum"}, {"source": "opus:phase3:8b24dc9e78606550571cbfad88325d266d65c09e93f170e3da164eb1207b655c", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "Over a timespan of approximately 1400 years, from the New Kingdom of Egypt to the end of the Ptolemaic Period"}, {"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-1500) = ''1500 - 500 BC'', categorize_period(-1390) = ''1500 - 500 BC'' - the same bucket"}, {"source": "residual", "url": "REASONS.json", "quote": "The field is open again, not corrected: the reversal withdraws a write the Opus re-verification did not confirm, and does not claim the restored value is right (opus_audit/RULES.md)."}]'::jsonb),
