    ('627ffcd0-ad25-4ff3-ae0d-5bc37d2053ef'::uuid, 'period_start', '-4500', '-4000', 'journal-reversal-3-rollback:627ffcd0-ad25-4ff3-ae0d-5bc37d2053ef:period_start', 'rollback of journal-reversal-3: period_start ''-4000'' restored on Chanhudaro', '[{"source": "remediation_change_log:29134", "url": "remediation_change_log", "quote": "phase3:batch-0244:chunk-0001 (P3/period_start): period_start ''-4500'' -> ''-4000'' - the write this row undoes"}, {"source": "opus:phase3:85e2c12c7e57af74a7d143d82a19476dd22abbda34cc3eedaf8219218c98ba08", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "The settlement was inhabited between 4000 and 1700 BCE"}, {"source": "opus:phase3:85e2c12c7e57af74a7d143d82a19476dd22abbda34cc3eedaf8219218c98ba08", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "Es handelt sich um die Reste einer Stadt der Indus-Kultur (ca. 2500–1900 v. Chr.)."}, {"source": "opus:phase3:85e2c12c7e57af74a7d143d82a19476dd22abbda34cc3eedaf8219218c98ba08", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "Die erste, die nochmals von den Ausgräbern in a, b und c unterteilt wurde, gehört der eigentlichen Indus-Kultur an"}, {"source": "opus:phase3:85e2c12c7e57af74a7d143d82a19476dd22abbda34cc3eedaf8219218c98ba08", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "Recent excavations have revealed new evidence of a pre-Indus settlement at the site, making Chanhu-daro a critical location for studying the entire chronological sequence of the Lower Indus Valley, from pre-Indus occupation (1st half of the 3rd millennium BCE) through the Indus urban period (Phase 1: 2600/2500-2300 BCE; Phase 2: 2300-2100/2000 BCE; Phase 3: 2100/2000-1900 BCE) to the post-Indus era (2nd millennium BCE)."}, {"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-4500) = ''4500 - 3000 BC'', categorize_period(-4000) = ''4500 - 3000 BC'' - the same bucket"}, {"source": "residual"