    ('74ea7fff-37dd-46f5-a3ca-2df0fdd65068'::uuid, 'period_start', '-4500', '-4000', 'journal-reversal-3-rollback:74ea7fff-37dd-46f5-a3ca-2df0fdd65068:period_start', 'rollback of journal-reversal-3: period_start ''-4000'' restored on Aghanaglack', '[{"source": "remediation_change_log:28320", "url": "remediation_change_log", "quote": "phase3:batch-0110:chunk-0003 (P3/period_start): period_start ''-4500'' -> ''-4000'' - the write this row undoes"}, {"source": "opus:phase3:000bc523421f9d49ea690c261268a85e800441c5d3159736cbb7fdd5e9ec6473", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "was excavated in the townland of Aghanaglack by Prof. Oliver Davies"}, {"source": "opus:phase3:000bc523421f9d49ea690c261268a85e800441c5d3159736cbb7fdd5e9ec6473", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "The tomb was found to contain Bronze Age and Stone Age items, pots, arrowheads and the remains of two children"}, {"source": "opus:phase3:000bc523421f9d49ea690c261268a85e800441c5d3159736cbb7fdd5e9ec6473", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "was excavated in the townland of Aghanaglack by Prof. Oliver Davies (4000"}, {"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-4500) = ''4500 - 3000 BC'', categorize_period(-4000) = ''4500 - 3000 BC'' - the same bucket"}, {"source": "residual", "url": "REASONS.json", "quote": "The field is open again, not corrected: the reversal withdraws a write the Opus re-verification did not confirm, and does not claim the restored value is right (opus_audit/RULES.md)."}]'::jsonb),
    ('75dccc9d-fb68-40a9-aa2e-e58a47067580'::uuid, 'period_start', '-500', '500', 'journal-reversal-3-rollback:75dccc9d-fb68-40a9-aa2e-e58a47067580:period_start', 'rollback of journal-reversal-3: period_start ''500'' restored on Elephanta Caves', '[{"source": "remediation_change_log:30922", "url": "remediation_change_log", "quote": "phase3:gap-0013:chunk-0001 (P3/period_start): period_start ''-500'' -> ''500'' - the write this row undoes"}, {"source": "opus:phase3:e602e5b9ca2b4945d036ecc6ee49463339494d5f6411a92a670aecd8bcfb1b17", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "The Elephanta site was first occupied by Hinayana Buddhists, before the arrival of the Brahmans to the island, to raise a large stupa to the Buddha with seven smaller stupas around it, probably around the 2nd century BCE."}, {"source": "opus:phase3:e602e5b9ca2b4945d036ecc6ee49463339494d5f6411a92a670aecd8bcfb1b17", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "This stupa, state Michell and Dhavalikar, was originally much taller and dates to about the 2nd century BCE."}, {"source": "opus:phase3:e602e5b9ca2b4945d036ecc6ee49463339494d5f6411a92a670aecd8bcfb1b17", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "It seems the Buddhists were the first occupants of the island."}, {"source": "opus:phase3:e602e5b9ca2b4945d036ecc6ee49463339494d5f6411a92a670aecd8bcfb1b17", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "features five Hindu caves, a few Buddhist stupa mounds that date back to the 2nd century BCE, and two Buddhist caves with water tanks"}, {"source": "opus:phase3:e602e5b9ca2b4945d036ecc6ee49463339494d5f6411a92a670aecd8bcfb1b17", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "Across the ravine from Cave 1 on the hill on the other side are two Buddhist caves, together with the remains of a stupa and water tanks. It seems the Buddhists were the first occupants of the island."}, {"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-500) = ''500 BC - 1 AD'', categorize_period(500) = ''500 - 1000 AD'' - another bucket"}, {"source": "residual", "url": "REASONS.json", "quote": "The field is open again, not corrected: the reversal withdraws a write the Opus re-verification did not confirm, and does not claim the restored value is right (opus_audit/RULES.md)."}]'::jsonb),
