    ('7eba70f1-aa71-47c7-9ccd-80ff5f1fb4cf'::uuid, 'period_start', '-6000', '-9500', 'journal-reversal-3-rollback:7eba70f1-aa71-47c7-9ccd-80ff5f1fb4cf:period_start', 'rollback of journal-reversal-3: period_start ''-9500'' restored on Osmantəpə', '[{"source": "remediation_change_log:28158", "url": "remediation_change_log", "quote": "phase3:batch-0084:chunk-0001 (P3/period_start): period_start ''-6000'' -> ''-9500'' - the write this row undoes"}, {"source": "opus:phase3:de470cd02a2eee6f69357a07473651932d9ed6a00edb0c7ea0916ea98a9ba899", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "the analysis of a carbon sample from the upper settlement layer indicated the dates in the 6th millennium BC."}, {"source": "opus:phase3:de470cd02a2eee6f69357a07473651932d9ed6a00edb0c7ea0916ea98a9ba899", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "Yaşayış yerinin üst təbəqəsindən götürülən karbon nümunənin analizi eramızdan əvvəl VI minilliyi göstərib."}, {"source": "opus:phase3:de470cd02a2eee6f69357a07473651932d9ed6a00edb0c7ea0916ea98a9ba899", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "A few other such very early Neolithic sites emerged almost simultaneously around 6000 BC in the foothills of the Lesser Caucasus Mountains."}, {"source": "opus:phase3:de470cd02a2eee6f69357a07473651932d9ed6a00edb0c7ea0916ea98a9ba899", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "is considered the oldest archaeological monument of the ceramic Neolithic. C14 measurements showed that the beginning of this settlement dates back to around 6200 BC."}, {"source": "opus:phase3:de470cd02a2eee6f69357a07473651932d9ed6a00edb0c7ea0916ea98a9ba899", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "the small number of ceramic finds at the settlement is consistent with an early phase of Ceramic Neolithic."}, {"source": "opus:phase3:de470cd02a2eee6f69357a07473651932d9ed6a00edb0c7ea0916ea98a9ba899", "url": "output/remediation/o