    ('97bdea94-4c2b-4508-83c3-777aaa16de29'::uuid, 'period_start', '-500', '1200', 'journal-reversal-3-rollback:97bdea94-4c2b-4508-83c3-777aaa16de29:period_start', 'rollback of journal-reversal-3: period_start ''1200'' restored on Lalibela', '[{"source": "remediation_change_log:29639", "url": "remediation_change_log", "quote": "phase3:batch-0318:chunk-0001 (P3/period_start): period_start ''-500'' -> ''1200'' - the write this row undoes"}, {"source": "opus:phase3:6da8bd8275d0c5cf63260eb4780263cc44d64e7ec393c9e5a64a1e9fc40e78fd", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "Recent archaeological excavations at Lalibela have yielded abundant pottery and faunal remains dating to 900"}, {"source": "opus:phase3:6da8bd8275d0c5cf63260eb4780263cc44d64e7ec393c9e5a64a1e9fc40e78fd", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "indicating that the site was largely a secular settlement before being transformed into a religious center by King Lalibela"}, {"source": "opus:phase3:6da8bd8275d0c5cf63260eb4780263cc44d64e7ec393c9e5a64a1e9fc40e78fd", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "The churches themselves date from the 7th to 13th centuries"}, {"source": "opus:phase3:6da8bd8275d0c5cf63260eb4780263cc44d64e7ec393c9e5a64a1e9fc40e78fd", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "indicating that the site was largely a secular settlement before being transformed into a religious center by King Lalibela."}, {"source": "opus:phase3:6da8bd8275d0c5cf63260eb4780263cc44d64e7ec393c9e5a64a1e9fc40e78fd", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "The churches themselves date from the 7th to 13th centuries, and are traditionally dated to the reign of the Zagwe (Agaw) king Gebre Meskel Lalibela"}, {"source": "opus:phase3:6da8bd8275d0c5cf63260eb4780263cc44d64e7ec393c9e5a64a1e9fc40e78fd", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "Though the dating of the churches