    ('c1c984e7-1391-4153-b140-f9bcd446d759'::uuid, 'period_start', '-1500', '-500', 'journal-reversal-3-rollback:c1c984e7-1391-4153-b140-f9bcd446d759:period_start', 'rollback of journal-reversal-3: period_start ''-500'' restored on Elche', '[{"source": "remediation_change_log:30903", "url": "remediation_change_log", "quote": "phase3:gap-0007:chunk-0003 (P3/period_start): period_start ''-1500'' -> ''-500'' - the write this row undoes"}, {"source": "opus:phase3:4df0788009f932ab9b764d8f7b1b19c3f07880ae919ede9fe278871721cfebbc", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "la secuencia estratigráfica abarca desde finales de la Edad del Bronce hasta principios de la época islámica"}, {"source": "opus:phase3:4df0788009f932ab9b764d8f7b1b19c3f07880ae919ede9fe278871721cfebbc", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "achieved the consolidation of its urban structure already by the early 5th century BCE"}, {"source": "opus:phase3:4df0788009f932ab9b764d8f7b1b19c3f07880ae919ede9fe278871721cfebbc", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "Aunque existen materiales arqueológicos de la fase neolítica, la secuencia estratigráfica alcanza, según los datos arqueológicos actuales, desde la Edad del Bronce hasta principios de la Islamización, aunque no siempre de forma continuada."}, {"source": "opus:phase3:4df0788009f932ab9b764d8f7b1b19c3f07880ae919ede9fe278871721cfebbc", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "Según los datos hallados la secuencia estratigráfica abarca desde finales de la Edad del Bronce hasta principios de la época islámica"}, {"source": "opus:phase3:4df0788009f932ab9b764d8f7b1b19c3f07880ae919ede9fe278871721cfebbc", "url": "output/remediation/opus_audit/DECISIONS.jsonl", "quote": "the neighbouring site of La Alcudia/Ilici achieved the consolidation of its urban structure already by the early 5th century BCE"}, {"source": "pipeline/utils/text.py:categorize_period", "url":